// Package database provides the relational database connection.
//
// Callers depend on Querier and WithinTx; the PostgreSQL implementation is in
// postgres.go.
package database

import (
	"context"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
)

// Name is the component name used in logs and readiness checks.
const Name = "database"

// Querier is what repositories run queries against. It matches the DBTX
// interface generated by sqlc, so generated code accepts it directly.
type Querier interface {
	Exec(ctx context.Context, sql string, args ...any) (pgconn.CommandTag, error)
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
}
